.btn-primary{background:#0d6efd;border:1px solid #0d6efd;color:#fff;border-radius:.25rem;padding:.375rem .9rem}
#pma_errors{color:#842029;background:#f8d7da;border:1px solid #f5c2c7;border-radius:.25rem}
.pma-footer-version{text-align:center;color:#6c757d;font-size:.75rem}
